package com.crm.identity.service;

import com.crm.identity.dto.*;import com.crm.identity.entity.*;import com.crm.identity.enums.RoleType;import com.crm.identity.repository.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.security.access.AccessDeniedException;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
import jakarta.validation.constraints.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;

@Service @Transactional(readOnly=true)
public class AccountAdministrationService {
 public static final Set<String> ACTIONS=Set.of("USER_CREATED","USER_UPDATED","ROLES_CHANGED","STATUS_CHANGED","SESSIONS_REVOKED","PASSWORD_CHANGED","DISPLAY_SETTINGS_CHANGED");
 private final UserRepository users;private final AdministrationEventRepository events;private final DisplaySettingsRepository settings;private final RefreshTokenRepository sessions;private final AdministrationJournal journal;private final jakarta.persistence.EntityManager em;
 public AccountAdministrationService(UserRepository u,AdministrationEventRepository e,DisplaySettingsRepository s,RefreshTokenRepository r,AdministrationJournal j,jakarta.persistence.EntityManager em){users=u;events=e;settings=s;sessions=r;journal=j;this.em=em;}
 public record UserView(String id,String firstName,String lastName,String username,String email,String phone,boolean enabled,boolean accountNonLocked,List<String> roles,boolean passwordChangeRequired,LocalDateTime createdAt){}
 public record EventView(String id,Instant occurredAt,String actorId,String targetId,String action,String outcome){}
 public record SettingsInput(@NotBlank @Size(max=100) String companyName,@NotNull @Size(max=100) @Email String supportEmail,@NotNull @Size(max=500) String welcomeMessage,@PositiveOrZero long version){}
 public record SettingsView(String companyName,String supportEmail,String welcomeMessage,long version){}
 public Page<UserView> directory(User actor,String keyword,String role,String state,int page,int size){require(actor,false);if(page<0||size<1||size>100||keyword!=null&&keyword.length()>200)throw new IllegalArgumentException("Invalid directory filters");RoleType wanted=role(role);if(state!=null&&!Set.of("active","disabled","locked").contains(state))throw new IllegalArgumentException("Invalid account state");String literal=keyword==null?"":keyword.trim().toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_");Specification<User> filter=(r,q,c)->{var p=new ArrayList<jakarta.persistence.criteria.Predicate>();if(!literal.isBlank())p.add(c.or(c.like(c.lower(r.get("username")),"%"+literal+"%",'\\'),c.like(c.lower(r.get("email")),"%"+literal+"%",'\\')));if(wanted!=null){q.distinct(true);p.add(c.equal(r.join("role").get("roleType"),wanted));}if(state!=null){if(state.equals("disabled"))p.add(c.isFalse(r.get("enabled")));else if(state.equals("locked"))p.add(c.isFalse(r.get("accountNonLocked")));else{p.add(c.isTrue(r.get("enabled")));p.add(c.isTrue(r.get("accountNonLocked")));}}return c.and(p.toArray(jakarta.persistence.criteria.Predicate[]::new));};return users.findAll(filter,PageRequest.of(page,size,Sort.by("id"))).map(this::view);}
 public Page<EventView> audit(User actor,LocalDate from,LocalDate to,String action,Long target,Long author,int page){require(actor,true);if(from==null||to==null||from.getYear()<1000||to.getYear()>9998||to.isBefore(from)||ChronoUnit.DAYS.between(from,to)>365||page<0||target!=null&&target<1||author!=null&&author<1)throw new IllegalArgumentException("At most 366 inclusive days");if(action!=null&&!ACTIONS.contains(action))throw new IllegalArgumentException("Unknown action");return events.search(from.atStartOfDay(ZoneOffset.UTC).toInstant(),to.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),action,target,author,PageRequest.of(page,20,Sort.by("id").descending())).map(this::event);}
 public EventView event(User actor,long id){require(actor,true);return event(events.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}
 public SettingsView display(){return setting(settings.findById(1L).orElseGet(DisplaySettings::new));}
 public SettingsView settings(User actor){require(actor,true);return display();}
 @Transactional public SettingsView updateSettings(User actor,SettingsInput input){require(actor,true);var validator=jakarta.validation.Validation.buildDefaultValidatorFactory();try{if(input==null||!validator.getValidator().validate(input).isEmpty())throw new IllegalArgumentException("Invalid display settings");}finally{validator.close();}var row=settings.lock().orElseThrow(()->new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Settings initialization required"));em.refresh(row,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);if(row.getVersion()!=input.version())throw new ResponseStatusException(HttpStatus.CONFLICT,"Settings changed; reload");row.update(input.companyName().trim(),input.supportEmail().trim(),input.welcomeMessage().trim());settings.flush();journal.record(actor,1L,"DISPLAY_SETTINGS_CHANGED");return setting(row);}
 @Transactional public void revoke(User actor,long id){require(actor,true);var user=users.lockById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));em.refresh(user,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);sessions.revokeAllByUser(user);journal.record(actor,id,"SESSIONS_REVOKED");}
 public void require(User actor,boolean superOnly){if(actor==null||!actor.isEnabled()||!actor.isAccountNonLocked()||actor.getRole().stream().noneMatch(r->r.getRoleType()==RoleType.SUPER_ADMIN||!superOnly&&r.getRoleType()==RoleType.ADMIN))throw new AccessDeniedException("Administrative access required");}
 private RoleType role(String value){if(value==null||value.isBlank())return null;try{return RoleType.valueOf(value);}catch(IllegalArgumentException ex){throw new IllegalArgumentException("Invalid account role");}}
 private UserView view(User u){return new UserView(u.getId().toString(),u.getFirstName(),u.getLastName(),u.getUsername(),u.getEmail(),u.getPhone(),u.isEnabled(),u.isAccountNonLocked(),u.getRole().stream().map(r->r.getRoleType().name()).sorted().toList(),u.isPasswordChangeRequired(),u.getCreatedAt());}
 private EventView event(AdministrationEvent e){return new EventView(e.getId().toString(),e.getOccurredAt(),e.getActorId()==null?null:e.getActorId().toString(),e.getTargetId().toString(),e.getAction(),e.getOutcome());}
 private SettingsView setting(DisplaySettings s){return new SettingsView(s.getCompanyName(),s.getSupportEmail(),s.getWelcomeMessage(),s.getVersion());}
}
